create policy "uploads read for signed in" on storage.objects for select to authenticated using (bucket_id = 'uploads');
create policy "uploads insert own folder" on storage.objects for insert to authenticated with check (bucket_id = 'uploads' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "uploads update own folder" on storage.objects for update to authenticated using (bucket_id = 'uploads' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "uploads delete own folder" on storage.objects for delete to authenticated using (bucket_id = 'uploads' and (storage.foldername(name))[1] = auth.uid()::text);